export type Profile = {
  id: string
  displayName: string
  version: number
}

export async function updateProfile(displayName: string): Promise<Profile> {
  const response = await fetch('/api/profile', {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ displayName }),
  })

  return response.json() as Promise<Profile>
}

// @vitest-environment jsdom

import '@testing-library/jest-dom/vitest'
import { act, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, expect, test, vi } from 'vitest'

import { ProfileForm } from './ProfileForm'

afterEach(() => {
  vi.unstubAllGlobals()
})

test('shows the new name while a successful save is pending', async () => {
  let resolveRequest: ((response: Response) => void) | undefined
  const response = new Promise<Response>((resolve) => {
    resolveRequest = resolve
  })
  vi.stubGlobal('fetch', vi.fn(() => response))

  const user = userEvent.setup()
  render(
    <ProfileForm profile={{ id: 'p1', displayName: 'Ada', version: 1 }} />,
  )

  await user.clear(screen.getByLabelText('Display name'))
  await user.type(screen.getByLabelText('Display name'), 'Grace')
  await user.click(screen.getByRole('button', { name: 'Save' }))

  expect(screen.getByLabelText('Current profile name')).toHaveTextContent(
    'Grace',
  )

  resolveRequest?.(
    new Response(
      JSON.stringify({ id: 'p1', displayName: 'Grace', version: 2 }),
      { status: 200, headers: { 'content-type': 'application/json' } },
    ),
  )
})

test('restores the authoritative name when a successful response has an invalid shape', async () => {
  vi.stubGlobal(
    'fetch',
    vi.fn(() =>
      Promise.resolve(
        new Response(
          JSON.stringify({ id: 'p1', displayName: 42, version: 'invalid' }),
          { status: 200, headers: { 'content-type': 'application/json' } },
        ),
      ),
    ),
  )

  const user = userEvent.setup()
  render(
    <ProfileForm profile={{ id: 'p1', displayName: 'Ada', version: 1 }} />,
  )

  await user.clear(screen.getByLabelText('Display name'))
  await user.type(screen.getByLabelText('Display name'), 'Grace')
  await user.click(screen.getByRole('button', { name: 'Save' }))

  expect(await screen.findByRole('alert')).toHaveTextContent(
    'Save failed. Please retry.',
  )
  expect(screen.getByLabelText('Current profile name')).toHaveTextContent('Ada')
})

test('rolls back to an older confirmed response when the latest overlapping save fails', async () => {
  const requests: Array<{
    resolve: (response: Response) => void
    reject: (error: Error) => void
  }> = []
  vi.stubGlobal(
    'fetch',
    vi.fn(
      () =>
        new Promise<Response>((resolve, reject) => {
          requests.push({ resolve, reject })
        }),
    ),
  )

  const user = userEvent.setup()
  render(
    <ProfileForm profile={{ id: 'p1', displayName: 'Ada', version: 1 }} />,
  )

  await user.clear(screen.getByLabelText('Display name'))
  await user.type(screen.getByLabelText('Display name'), 'Grace')
  await user.click(screen.getByRole('button', { name: 'Save' }))
  await user.clear(screen.getByLabelText('Display name'))
  await user.type(screen.getByLabelText('Display name'), 'Lin')
  await user.click(screen.getByRole('button', { name: 'Save' }))

  await act(async () => {
    requests[0]?.resolve(
      new Response(
        JSON.stringify({ id: 'p1', displayName: 'Grace', version: 2 }),
        { status: 200, headers: { 'content-type': 'application/json' } },
      ),
    )
  })
  expect(screen.getByLabelText('Current profile name')).toHaveTextContent('Lin')

  await act(async () => {
    requests[1]?.reject(new Error('network unavailable'))
  })

  expect(await screen.findByRole('alert')).toHaveTextContent(
    'Save failed. Please retry.',
  )
  expect(screen.getByLabelText('Current profile name')).toHaveTextContent(
    'Grace',
  )
})

import { type FormEvent, useState } from 'react'

import { type Profile, updateProfile } from './api'

export function ProfileForm({ profile }: { profile: Profile }) {
  const [displayName, setDisplayName] = useState(profile.displayName)
  const [visibleName, setVisibleName] = useState(profile.displayName)

  async function handleSubmit(event: FormEvent) {
    event.preventDefault()
    setVisibleName(displayName)
    await updateProfile(displayName)
  }

  return (
    <form onSubmit={handleSubmit}>
      <p aria-label="Current profile name">{visibleName}</p>
      <label>
        Display name
        <input
          value={displayName}
          onChange={(event) => setDisplayName(event.target.value)}
        />
      </label>
      <button>Save</button>
    </form>
  )
}

import { type FormEvent, useReducer, useRef, useState } from 'react'

import { type Profile, updateProfile } from './api'

type PendingSave = {
  requestId: number
  displayName: string
}

type SaveState = {
  confirmedProfile: Profile
  pendingSave: PendingSave | null
  failedDisplayName: string | null
  latestSuccessfulRequestId: number
}

type SaveAction =
  | { type: 'submitted'; save: PendingSave }
  | { type: 'succeeded'; requestId: number; profile: Profile }
  | { type: 'failed'; save: PendingSave }

function saveReducer(state: SaveState, action: SaveAction): SaveState {
  if (action.type === 'submitted') {
    return {
      ...state,
      pendingSave: action.save,
      failedDisplayName: null,
    }
  }

  if (action.type === 'succeeded') {
    if (action.requestId < state.latestSuccessfulRequestId) return state

    const confirmedProfile =
      action.profile.version > state.confirmedProfile.version
        ? action.profile
        : state.confirmedProfile

    return {
      ...state,
      confirmedProfile,
      pendingSave:
        state.pendingSave?.requestId === action.requestId
          ? null
          : state.pendingSave,
      latestSuccessfulRequestId: action.requestId,
    }
  }

  if (state.pendingSave?.requestId !== action.save.requestId) return state

  return {
    ...state,
    pendingSave: null,
    failedDisplayName: action.save.displayName,
  }
}

export function ProfileForm({ profile }: { profile: Profile }) {
  const [displayName, setDisplayName] = useState(profile.displayName)
  const [saveState, dispatch] = useReducer(saveReducer, {
    confirmedProfile: profile,
    pendingSave: null,
    failedDisplayName: null,
    latestSuccessfulRequestId: 0,
  })
  const nextRequestId = useRef(0)

  async function save(nextDisplayName: string) {
    const pendingSave = {
      requestId: ++nextRequestId.current,
      displayName: nextDisplayName,
    }
    dispatch({ type: 'submitted', save: pendingSave })

    try {
      const updatedProfile = await updateProfile(nextDisplayName)
      if (updatedProfile.id !== profile.id) {
        throw new Error('Profile update returned a different profile')
      }
      dispatch({
        type: 'succeeded',
        requestId: pendingSave.requestId,
        profile: updatedProfile,
      })
    } catch {
      dispatch({ type: 'failed', save: pendingSave })
    }
  }

  function handleSubmit(event: FormEvent) {
    event.preventDefault()
    void save(displayName)
  }

  const visibleName =
    saveState.pendingSave?.displayName ??
    saveState.confirmedProfile.displayName

  return (
    <form onSubmit={handleSubmit}>
      <p aria-label="Current profile name">{visibleName}</p>
      <label>
        Display name
        <input
          value={displayName}
          onChange={(event) => setDisplayName(event.target.value)}
        />
      </label>
      <button type="submit">Save</button>
      {saveState.failedDisplayName !== null && (
        <div role="alert">
          Save failed. Please retry.
          <button
            type="button"
            onClick={() => void save(saveState.failedDisplayName!)}
          >
            Retry
          </button>
        </div>
      )}
    </form>
  )
}

export type Profile = {
  id: string
  displayName: string
  version: number
}

function isProfile(value: unknown): value is Profile {
  if (typeof value !== 'object' || value === null) return false

  const profile = value as Record<string, unknown>
  return (
    typeof profile.id === 'string' &&
    typeof profile.displayName === 'string' &&
    typeof profile.version === 'number' &&
    Number.isInteger(profile.version) &&
    profile.version >= 0
  )
}

export async function updateProfile(displayName: string): Promise<Profile> {
  const response = await fetch('/api/profile', {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ displayName }),
  })

  if (!response.ok) {
    throw new Error(`Profile update failed with status ${response.status}`)
  }

  const profile: unknown = await response.json()
  if (!isProfile(profile)) {
    throw new Error('Profile update returned an invalid response')
  }

  return profile
}
